{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "PEMA, the highest-transfer analogue, showed absolute oral bioavailability of at least 80% in normal subjects, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Odanacatib, which shares an aryl methylsulfone with the query, had absolute oral bioavailability of 30% (90% CI 27-34%) at 50 mg fasted in humans, still above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Encainide, despite first-pass metabolism, showed absolute oral bioavailability of 20-30% in healthy subjects, at or above the F >= 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Pentopril showed absolute oral bioavailability greater than 58% in humans, supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin, a heteroaromatic amide with a basic center, had absolute oral bioavailability of 57.8% (95% CI 54.1-61.4) in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Vilazodone, containing a carboxamide and piperazine, had absolute oral bioavailability of 72% in humans when taken with food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Trazodone, a tricyclic arylpiperazine, had absolute systemic availability averaging 72-91% across age and sex groups, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Carbamazepine epoxide, a tricyclic epoxide urea, had absolute oral bioavailability of 60% (95% CI 49-75%) for an immediate-release oral formulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Flupentixol, a tricyclic antipsychotic with a piperazine side chain, had mean oral systemic availability of 55% in volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Benazeprilat had absolute oral bioavailability of 27.1-28.5%, the lowest among the analogues but still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten evidence molecules, with assay-transfer scores of 0.987-0.989, show absolute oral bioavailability at or above 20% in humans, with most values between 30% and 90%. The lowest reported values (encainide 20-30%, benazeprilat 27-28.5%) still meet the F >= 20% threshold. The query's tricyclic sulfonamide/piperidine-carboxamide scaffold is consistent with these analogues, and no evidence supports low bioavailability. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study exists for the query molecule itself.",
    "Food effects and dose-dependent solubility-limited absorption for the query are unknown.",
    "The query-specific balance of first-pass metabolism, efflux transport, and permeability has not been directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

